validator:
function validate(input) {
  const [{ prompts = [] }] = input;
  const seen = new Set();
  for (const [user, prompt, tokens] of prompts) {
    if (user === null || prompt === null || tokens === null) return 'No column may be null.';
    const key = `${user}|${String(prompt).toLowerCase()}`;
    if (seen.has(key)) return `User ${user} submits "${prompt}" twice.`;
    seen.add(key);
    if (!(Number.isInteger(tokens) && tokens >= 1)) return `tokens ${tokens} must be a positive integer.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const pick = n => Math.floor(rand() * n);
  const topics = ['Write a blog outline', 'Generate SQL query', 'Summarize an article', 'Create resume bullet', 'Explain neural networks', 'Write cover letter', 'Optimize Python code', 'Translate an email'];
  const levels = small ? [60, 80, 100, 100, 120, 200] : null;
  const prompts = [];
  let budget = small ? pick(9) : 2000;
  for (let user = small ? 1 : 100; budget > 0; user++) {
    // At most 30 prompts per user: an average that ends in a rounding tie is then a multiple of 1/8, exact in
    // binary, so ROUND(AVG(tokens), 2) agrees with MySQL's exact decimal rounding (40 prompts could break that).
    const count = Math.min(budget, small ? 1 + pick(5) : 1 + pick(30));
    budget -= count;
    // Some users always spend the same number of tokens, so no prompt beats their average.
    const flat = rand() < 0.25;
    const base = small ? levels[pick(levels.length)] : 10 + pick(990);
    for (let i = 0; i < count; i++) {
      const tokens = flat ? base : small ? levels[pick(levels.length)] : 10 + pick(990);
      const name = i < topics.length ? topics[i] : `${topics[i % topics.length]} #${Math.floor(i / topics.length) + 1}`;
      prompts.push([user, name, tokens]);
    }
  }
  return [{ prompts }];
}
